-- Fix: The original migration set feature_version DEFAULT 1 and recommendation_features DEFAULT '{}'. -- This caused unbackfilled hackathons to appear "processed", skipping runtime tag extraction -- and producing uniform recommendation scores. -- Reset feature_version to 0 for hackathons that were never actually processed UPDATE hackathons SET feature_version = 0, recommendation_features = NULL WHERE feature_version = 1 AND (tags = '{}' OR tags IS NULL) AND (recommendation_features = '{}'::jsonb OR recommendation_features IS NULL); -- Fix column defaults for future inserts ALTER TABLE hackathons ALTER COLUMN feature_version SET DEFAULT 0, ALTER COLUMN recommendation_features DROP NOT NULL, ALTER COLUMN recommendation_features DROP DEFAULT;;
